  1→import { db } from "@/db";
  2→import { skills, skillRelationsTable } from "@/db/schema";
  3→import { requireAuth } from "@/lib/api/auth";
  4→import { ok, error, handleError } from "@/lib/api/response";
  5→import { eq, and, or, inArray } from "drizzle-orm";
  6→
  7→/**
  8→ * Pull endpoint for AI clients (Craft Agent, Claude Code).
  9→ * Returns all relevant skills as SKILL.md format (Markdown with YAML frontmatter),
 10→ * ready to be written to the local filesystem.
 11→ *
 12→ * GET /api/skills/pull?orgId=xxx&projectId=yyy&authorId=zzz
 13→ * Optional: &root=slug&depth=2 — only skills reachable from root
 14→ *
 15→ * Returns: global + project + personal skills, merged.
 16→ * On slug collision: personal > project > global.
 17→ * Relations are included in frontmatter. Priority 1 deps are inlined, 2+ as reference markers.
 18→ */
 19→export async function GET(request: Request) {
 20→  try {
 21→    const user = await requireAuth();
 22→    const { searchParams } = new URL(request.url);
 23→    const orgId = searchParams.get("orgId");
 24→    const projectId = searchParams.get("projectId");
 25→    const authorId = searchParams.get("authorId") ?? user.id;
 26→    const rootSlug = searchParams.get("root");
 27→    const depth = Math.min(parseInt(searchParams.get("depth") ?? "0") || 0, 10);
 28→
 29→    if (!orgId) return error("orgId is required", 400);
 30→
 31→    // Build conditions: global OR (project match) OR (author match)
 32→    const isValidUuid =
 33→      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
 34→        authorId
 35→      );
 36→
 37→    const scopeConditions = [
 38→      eq(skills.scope, "global"),
 39→      ...(projectId
 40→        ? [and(eq(skills.scope, "project"), eq(skills.projectId, projectId))]
 41→        : []),
 42→      ...(isValidUuid
 43→        ? [and(eq(skills.scope, "personal"), eq(skills.authorId, authorId))]
 44→        : []),
 45→    ];
 46→
 47→    const result = await db.query.skills.findMany({
 48→      where: and(eq(skills.orgId, orgId), or(...scopeConditions)),
 49→      with: { resources: true, tags: true },
 50→      orderBy: (s, { asc }) => [asc(s.name)],
 51→    });
 52→
 53→    // Deduplicate by slug: personal > project > global
 54→    const scopePriority = { personal: 2, project: 1, global: 0 } as const;
 55→    const bySlug = new Map<string, (typeof result)[number]>();
 56→
 57→    for (const skill of result) {
 58→      const existing = bySlug.get(skill.slug);
 59→      if (
 60→        !existing ||
 61→        scopePriority[skill.scope] > scopePriority[existing.scope]
 62→      ) {
 63→        bySlug.set(skill.slug, skill);
 64→      }
 65→    }
 66→
 67→    let deduped = Array.from(bySlug.values());
 68→    const skillIds = deduped.map((s) => s.id);
 69→
 70→    // Load all outgoing relations for these skills
 71→    const allRelations =
 72→      skillIds.length > 0
 73→        ? await db.query.skillRelationsTable.findMany({
 74→            where: inArray(skillRelationsTable.sourceSkillId, skillIds),
 75→            with: {
 76→              targetSkill: {
 77→                columns: { id: true, slug: true, name: true, content: true },
 78→              },
 79→            },
 80→          })
 81→        : [];
 82→
 83→    // If root slug is specified, filter to reachable skills
 84→    if (rootSlug && depth > 0) {
 85→      const rootSkill = deduped.find((s) => s.slug === rootSlug);
 86→      if (rootSkill) {
 87→        const idBySlug = new Map(deduped.map((s) => [s.id, s]));
 88→        const reachable = new Set<string>([rootSkill.id]);
 89→        let frontier = new Set<string>([rootSkill.id]);
 90→
 91→        for (let d = 0; d < depth; d++) {
 92→          const nextFrontier = new Set<string>();
 93→          for (const rel of allRelations) {
 94→            if (frontier.has(rel.sourceSkillId) && !reachable.has(rel.targetSkillId)) {
 95→              reachable.add(rel.targetSkillId);
 96→              nextFrontier.add(rel.targetSkillId);
 97→            }
 98→          }
 99→          // Also check incoming relations for bidirectional traversal
100→          for (const rel of allRelations) {
101→            if (frontier.has(rel.targetSkill.id) && !reachable.has(rel.sourceSkillId)) {
102→              reachable.add(rel.sourceSkillId);
103→              nextFrontier.add(rel.sourceSkillId);
104→            }
105→          }
106→          frontier = nextFrontier;
107→          if (frontier.size === 0) break;
108→        }
109→
110→        deduped = deduped.filter((s) => reachable.has(s.id));
111→      }
112→    }
113→
114→    // Group relations by source skill ID
115→    const relationsBySkill = new Map<string, typeof allRelations>();
116→    for (const rel of allRelations) {
117→      const list = relationsBySkill.get(rel.sourceSkillId) ?? [];
118→      list.push(rel);
119→      relationsBySkill.set(rel.sourceSkillId, list);
120→    }
121→
122→    // Format as SKILL.md content
123→    const formatted = deduped.map((skill) => {
124→      const rels = relationsBySkill.get(skill.id) ?? [];
125→      const tags = skill.tags.map((t) => t.tag);
126→
127→      // Build relations frontmatter
128→      const relationsYaml =
129→        rels.length > 0
130→          ? [
131→              "relations:",
132→              ...rels.map((r) => {
133→                const lines = [
134→                  `  - slug: ${r.targetSkill.slug}`,
135→                  `    type: ${r.relationType}`,
136→                  `    priority: ${(r as typeof r & { priority: number }).priority ?? 1}`,
137→                ];
138→                if (r.context) {
139→                  lines.push(
140→                    `    context: '${r.context.replace(/'/g, "''")}'`
141→                  );
142→                }
143→                return lines.join("\n");
144→              }),
145→            ].join("\n")
146→          : null;
147→
148→      const frontmatter = [
149→        "---",
150→        `name: '${skill.name}'`,
151→        `description: '${skill.description.replace(/'/g, "''")}'`,
152→        ...(skill.globs.length
153→          ? [`globs: ${JSON.stringify(skill.globs)}`]
154→          : []),
155→        ...(skill.alwaysAllow.length
156→          ? [`alwaysAllow: ${JSON.stringify(skill.alwaysAllow)}`]
157→          : []),
158→        ...(tags.length ? [`tags: ${JSON.stringify(tags)}`] : []),
159→        ...(relationsYaml ? [relationsYaml] : []),
160→        "---",
161→      ].join("\n");
162→
163→      // Priority 1: inline full content. Priority 2+: reference marker only
164→      const inlineDeps = rels
165→        .filter(
166→          (r) =>
167→            r.relationType === "depends_on" || r.relationType === "extends"
168→        )
169→        .map((r) => {
170→          const priority = (r as typeof r & { priority: number }).priority ?? 1;
171→          if (priority === 1) {
172→            return `\n\n## Abhängigkeit: ${r.targetSkill.name}\n\n${r.targetSkill.content}`;
173→          }
174→          return `\n\n<!-- depends_on: ${r.targetSkill.slug} (priority: ${priority}) -->`;
175→        })
176→        .join("");
177→
178→      return {
179→        slug: skill.slug,
180→        scope: skill.scope,
181→        version: skill.version,
182→        filename: "SKILL.md",
183→        content: `${frontmatter}\n\n${skill.content}${inlineDeps}`,
184→        resources: skill.resources.map((r) => ({
185→          path: r.path,
186→          content: r.content,
187→        })),
188→      };
189→    });
190→
191→    return ok({ skills: formatted });
192→  } catch (err) {
193→    return handleError(err);
194→  }
195→}
