216→function findProjectRoot(): string | null {
217→  let dir = process.cwd();
218→  for (let i = 0; i < 10; i++) {
219→    if (existsSync(join(dir, "package.json")) && existsSync(join(dir, "packages", "cli"))) {
220→      return dir;
