233→function prompt(question: string): Promise<string> {
234→  const rl = createInterface({ input: process.stdin, output: process.stdout });
235→  return new Promise((resolve) => {
236→    rl.question(question, (answer) => {
237→      rl.close();
238→      resolve(answer.trim());
239→    });
240→  });
241→}
