151→
152→      if (opts.human) {
153→        const scope = { global: "[G]", project: "[P]", personal: "[U]" }[skill.scope as string] ?? "[?]";
154→        const resCount = skill.resources?.length ?? 0;
155→        const resLabel = resCount > 0 ? ` (+${resCount} resources)` : "";
156→        console.log(`  ${scope} ${skill.slug} v${skill.version}${resLabel}`);
