 37→function parseSkillMd(content: string) {
 38→  const fmMatch = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
 39→  if (!fmMatch) throw new Error("No frontmatter found");
 40→
 41→  const frontmatter = fmMatch[1];
 42→  const body = fmMatch[2].trim();
 43→
 44→  // Simple YAML parsing for the fields we need
 45→  const name =
 46→    frontmatter.match(/name:\s*['"]?(.*?)['"]?\s*$/m)?.[1] ?? "Unknown";
 47→  const description =
 48→    frontmatter.match(/description:\s*['"]?([\s\S]*?)['"]?\s*$/m)?.[1] ?? "";
 49→
 50→  // Parse globs (YAML array)
 51→  let globs: string[] = [];
 52→  const globLine = frontmatter.match(/globs:\s*\[([^\]]*)\]/);
 53→  if (globLine) {
 54→    globs = globLine[1]
 55→      .split(",")
