150→function resolveRipgrepPath(hostRuntime: BackendHostRuntimeContext): string | undefined {
151→  const platform = process.platform === 'win32'
152→    ? 'x64-win32'
153→    : process.platform === 'darwin'
154→      ? (process.arch === 'arm64' ? 'arm64-darwin' : 'x64-darwin')
155→      : (process.arch === 'arm64' ? 'arm64-linux' : 'x64-linux');
156→  const binaryName = process.platform === 'win32' ? 'rg.exe' : 'rg';
157→  const ripgrepRelative = join(
158→    'node_modules',
159→    '@anthropic-ai',
160→    'claude-agent-sdk',
161→    'vendor',
162→    'ripgrep',
163→    platform,
164→    binaryName,
165→  );
166→
167→  if (hostRuntime.isPackaged) {
168→    const packaged = join(hostRuntime.appRootPath, ripgrepRelative);
169→    if (existsSync(packaged)) return packaged;
170→  }
171→
172→  const fromHostRoot = resolveUpwards(hostRuntime.appRootPath, ripgrepRelative, 10);
173→  if (fromHostRoot) return fromHostRoot;
174→
175→  const cwdFallback = join(process.cwd(), ripgrepRelative);
176→  if (existsSync(cwdFallback)) return cwdFallback;
177→
178→  // Non-packaged (headless server, dev mode): fall back to system rg via PATH.
179→  // Packaged apps must use vendored binary only — never resolve from PATH
180→  // to avoid picking up an incompatible system install.
181→  if (!hostRuntime.isPackaged) {
182→    try {
183→      const whichCmd = process.platform === 'win32' ? 'where' : 'which';
184→      const systemRg = execFileSync(whichCmd, ['rg'], { encoding: 'utf-8' }).trim();
185→      if (systemRg && existsSync(systemRg)) return systemRg;
186→    } catch { /* system rg not found */ }
187→  }
188→
189→  return undefined;
190→}
