195→  return {
196→    claudeCliPath: resolveClaudeCliPath(hostRuntime),
197→    claudeInterceptorPath: resolveClaudeInterceptorPath(hostRuntime),
198→    interceptorBundlePath: resolveInterceptorBundlePath(hostRuntime),
199→    copilotCliPath: resolveCopilotCliPath(hostRuntime),
200→    sessionServerPath: resolveServerPath(hostRuntime, 'session-mcp-server'),
201→    bridgeServerPath: resolveServerPath(hostRuntime, 'bridge-mcp-server'),
202→    piServerPath: resolveServerPath(hostRuntime, 'pi-agent-server'),
203→    nodeRuntimePath: hostRuntime.nodeRuntimePath || bundledRuntimePath || process.execPath,
204→    bundledRuntimePath,
205→  };
206→}
