214→/**
215→ * Configure anthropic-sdk globals from host runtime context.
216→ * This mirrors previous Electron bootstrap behavior but keeps it behind backend internals.
217→ *
218→ * When `strict` is true (default), throws on missing SDK, interceptor, or bundled runtime.
219→ * When `strict` is false, sets paths opportunistically — missing paths are silently skipped.
220→ */
221→export function applyAnthropicRuntimeBootstrap(
222→  hostRuntime: BackendHostRuntimeContext,
223→  paths: ResolvedBackendRuntimePaths,
224→  options?: { strict?: boolean },
225→): void {
226→  const strict = options?.strict ?? true;
227→
228→  if (paths.claudeCliPath) {
229→    setPathToClaudeCodeExecutable(paths.claudeCliPath);
230→  } else if (strict) {
231→    throw new Error('Claude Code SDK not found. The app package may be corrupted.');
232→  }
233→
234→  if (paths.claudeInterceptorPath) {
235→    setInterceptorPath(paths.claudeInterceptorPath);
236→  } else if (strict) {
237→    throw new Error('Network interceptor not found. The app package may be corrupted.');
238→  }
239→
240→  if (hostRuntime.isPackaged) {
241→    if (paths.bundledRuntimePath) {
242→      setExecutable(paths.bundledRuntimePath);
243→    } else if (strict) {
244→      throw new Error('Bundled Bun runtime not found. The app package may be corrupted.');
245→    }
246→  } else if (process.env.CRAFT_BUN) {
247→    // Dev mode: use CRAFT_BUN env var if set (e.g. when running fork alongside official app)
248→    setExecutable(process.env.CRAFT_BUN);
249→  }
250→}
