 55→export function getBunDownloadName(platform: Platform, arch: Arch): string {
 56→  const archMap: Record<Arch, string> = {
 57→    x64: 'x64',
 58→    arm64: 'aarch64',
 59→  };
 60→
 61→  const platformMap: Record<Platform, string> = {
 62→    darwin: 'darwin',
 63→    win32: 'windows',
 64→    linux: 'linux',
 65→  };
