 92→/**
 93→ * Verify SHA256 checksum of a file
 94→ */
 95→export async function verifySha256(filePath: string, expectedHash: string): Promise<boolean> {
 96→  const file = Bun.file(filePath);
 97→  const buffer = await file.arrayBuffer();
 98→  const hash = createHash('sha256').update(Buffer.from(buffer)).digest('hex');
 99→  return hash.toLowerCase() === expectedHash.toLowerCase();
100→}
