102→/**
103→ * Download and verify Bun binary
104→ * Uses curl for downloads (more reliable in CI than fetch + Bun.write)
105→ */
106→export async function downloadBun(config: BuildConfig): Promise<void> {
107→  const { platform, arch, electronDir } = config;
108→  const bunDownload = getBunDownloadName(platform, arch);
109→  const vendorDir = join(electronDir, 'vendor', 'bun');
110→
111→  console.log(`Downloading Bun ${BUN_VERSION} for ${platform}-${arch}...`);
112→
113→  // Create vendor directory
114→  mkdirSync(vendorDir, { recursive: true });
115→
116→  // Create temp directory
117→  const tempDir = join(electronDir, '.bun-download-temp');
118→  mkdirSync(tempDir, { recursive: true });
119→
120→  try {
121→    const zipUrl = `https://github.com/oven-sh/bun/releases/download/${BUN_VERSION}/${bunDownload}.zip`;
122→    const checksumUrl = `https://github.com/oven-sh/bun/releases/download/${BUN_VERSION}/SHASUMS256.txt`;
123→
124→    // Download files using curl (more reliable in CI than fetch + Bun.write)
125→    const zipPath = join(tempDir, `${bunDownload}.zip`);
126→    const checksumPath = join(tempDir, 'SHASUMS256.txt');
127→
128→    console.log(`  Downloading ${zipUrl}...`);
129→    await $`curl -fsSL --retry 3 --retry-delay 2 -o ${zipPath} ${zipUrl}`;
130→    console.log('  Download complete');
131→
132→    console.log('  Downloading checksums...');
133→    await $`curl -fsSL --retry 3 --retry-delay 2 -o ${checksumPath} ${checksumUrl}`;
134→
135→    // Verify checksum
136→    console.log('  Verifying checksum...');
137→    const checksumContent = await Bun.file(checksumPath).text();
138→    const expectedHash = checksumContent
139→      .split('\n')
140→      .find((line) => line.includes(`${bunDownload}.zip`))
141→      ?.split(' ')[0];
142→
143→    if (!expectedHash) {
144→      throw new Error(`Checksum not found for ${bunDownload}.zip`);
145→    }
146→
147→    const isValid = await verifySha256(zipPath, expectedHash);
148→    if (!isValid) {
149→      throw new Error('Checksum verification failed!');
150→    }
151→    console.log('  Checksum verified ✓');
152→
153→    // Extract
154→    console.log('  Extracting...');
155→    await $`unzip -o ${zipPath} -d ${tempDir}`.quiet();
156→
157→    // Copy binary
158→    const bunBinary = platform === 'win32' ? 'bun.exe' : 'bun';
159→    const sourcePath = join(tempDir, bunDownload, bunBinary);
160→    const destPath = join(vendorDir, bunBinary);
161→
162→    copyFileSync(sourcePath, destPath);
163→
164→    // Make executable on Unix
165→    if (platform !== 'win32') {
166→      await $`chmod +x ${destPath}`.quiet();
167→    }
168→
169→    console.log(`  Bun installed to ${destPath} ✓`);
170→  } finally {
171→    // Cleanup temp directory
172→    rmSync(tempDir, { recursive: true, force: true });
173→  }
174→}
