176→/**
177→ * Find the first matching file recursively under a directory.
178→ */
179→function findFileRecursive(root: string, fileName: string): string | null {
180→  const entries = readdirSync(root, { withFileTypes: true });
181→  for (const entry of entries) {
182→    const fullPath = join(root, entry.name);
183→    if (entry.isFile() && entry.name === fileName) {
184→      return fullPath;
185→    }
186→    if (entry.isDirectory()) {
187→      const nested = findFileRecursive(fullPath, fileName);
188→      if (nested) return nested;
189→    }
190→  }
191→  return null;
192→}
