217→  mkdirSync(tempDir, { recursive: true });
218→
219→  try {
220→    const assetUrl = `https://github.com/astral-sh/uv/releases/download/${UV_VERSION}/${uvDownload}`;
221→    const checksumUrl = `${assetUrl}.sha256`;
222→
223→    const assetPath = join(tempDir, uvDownload);
224→    const checksumPath = join(tempDir, `${uvDownload}.sha256`);
225→    const extractDir = join(tempDir, 'extract');
226→
227→    console.log(`  Downloading ${assetUrl}...`);
228→    await $`curl -fsSL --retry 3 --retry-delay 2 -o ${assetPath} ${assetUrl}`;
229→
230→    console.log('  Downloading checksum...');
231→    await $`curl -fsSL --retry 3 --retry-delay 2 -o ${checksumPath} ${checksumUrl}`;
232→
233→    console.log('  Verifying checksum...');
234→    const checksumContent = await Bun.file(checksumPath).text();
235→    const hashMatch = checksumContent.match(/[a-fA-F0-9]{64}/);
236→    if (!hashMatch) {
237→      throw new Error(`Unable to parse checksum from ${checksumPath}`);
238→    }
239→
240→    const isValid = await verifySha256(assetPath, hashMatch[0]);
241→    if (!isValid) {
242→      throw new Error('uv checksum verification failed');
243→    }
244→    console.log('  Checksum verified ✓');
245→
246→    mkdirSync(extractDir, { recursive: true });
247→
248→    if (uvDownload.endsWith('.zip')) {
249→      // Use PowerShell on Windows for consistent extraction support.
250→      await $`powershell -NoProfile -ExecutionPolicy Bypass -Command "Expand-Archive -LiteralPath '${assetPath}' -DestinationPath '${extractDir}' -Force"`;
251→    } else {
252→      await $`tar -xzf ${assetPath} -C ${extractDir}`;
253→    }
254→
255→    const extractedUv = findFileRecursive(extractDir, uvBinaryName);
256→    if (!extractedUv) {
257→      throw new Error(`Unable to locate ${uvBinaryName} in extracted archive`);
258→    }
259→
260→    copyFileSync(extractedUv, targetPath);
261→    if (platform !== 'win32') {
262→      await $`chmod +x ${targetPath}`.quiet();
263→    }
264→
265→    console.log(`  uv installed to ${targetPath} ✓`);
266→  } finally {
267→    rmSync(tempDir, { recursive: true, force: true });
268→  }
269→}
