444→/**
445→ * Copy Pi Agent Server to packaged app resources.
446→ *
447→ * The bun build uses --external koffi so the bare import resolves through
448→ * node_modules at runtime. We copy the koffi npm package next to index.js
449→ * with only the target platform's native binary (~4MB instead of ~80MB).
450→ */
451→export function copyPiAgentServer(config: BuildConfig): void {
452→  const { rootDir, electronDir, platform, arch } = config;
453→
454→  const piSourceDir = join(rootDir, 'packages', 'pi-agent-server', 'dist');
455→  const piDestDir = join(electronDir, 'resources', 'pi-agent-server');
456→
457→  if (!existsSync(join(piSourceDir, 'index.js'))) {
458→    console.warn(`Warning: Pi agent server not found at ${piSourceDir}/index.js. Pi SDK sessions will not work.`);
459→    return;
460→  }
461→
462→  console.log('Copying Pi Agent Server...');
463→  mkdirSync(piDestDir, { recursive: true });
464→
465→  // 1. Copy index.js
466→  copyFileSync(join(piSourceDir, 'index.js'), join(piDestDir, 'index.js'));
467→
468→  // 2. Copy koffi npm package (external import, resolved via node_modules at runtime)
469→  const koffiSource = join(rootDir, 'node_modules', 'koffi');
470→
471→  if (!existsSync(koffiSource)) {
472→    console.warn('  Warning: koffi not found in node_modules. Pi SDK sessions may not work.');
473→    return;
474→  }
475→
476→  const koffiDest = join(piDestDir, 'node_modules', 'koffi');
477→  mkdirSync(koffiDest, { recursive: true });
478→
479→  // Copy koffi JS files
480→  for (const entry of ['package.json', 'index.js', 'indirect.js', 'index.d.ts', 'lib']) {
481→    const src = join(koffiSource, entry);
482→    if (existsSync(src)) {
483→      cpSync(src, join(koffiDest, entry), { recursive: true });
484→    }
485→  }
486→
487→  // Copy only the target platform's native binary
488→  const targetDir = koffiPlatformDir(platform, arch);
489→  const nativeSrc = join(koffiSource, 'build', 'koffi', targetDir);
490→  const nativeDest = join(koffiDest, 'build', 'koffi', targetDir);
491→
492→  if (existsSync(nativeSrc)) {
493→    mkdirSync(nativeDest, { recursive: true });
494→    cpSync(nativeSrc, nativeDest, { recursive: true });
495→    const size = lstatSync(join(nativeSrc, readdirSync(nativeSrc)[0])).size;
496→    console.log(`  Copied index.js + koffi/${targetDir} (${(size / 1024 / 1024).toFixed(1)}MB)`);
497→  } else {
498→    console.warn(`  Warning: koffi native binary not found for ${targetDir}`);
499→    cpSync(join(koffiSource, 'build'), join(koffiDest, 'build'), { recursive: true });
500→    console.log('  Copied index.js + koffi (all platforms as fallback)');
501→  }
502→}
