504→/**
505→ * Build MCP servers (session) and Pi agent server.
506→ * Shared across all platforms to avoid drift.
507→ */
508→export function buildMcpServers(config: BuildConfig): void {
509→  const { rootDir } = config;
510→
511→  const sessionDir = join(rootDir, 'packages', 'session-mcp-server');
512→  const sessionOut = join(sessionDir, 'dist', 'index.js');
513→  const piDir = join(rootDir, 'packages', 'pi-agent-server');
514→  const piOut = join(piDir, 'dist', 'index.js');
515→
516→  console.log('Building MCP servers...');
517→
518→  mkdirSync(join(sessionDir, 'dist'), { recursive: true });
519→
520→  execSync(
521→    `bun build ${join(sessionDir, 'src', 'index.ts')} --outfile ${sessionOut} --target node --format cjs`,
522→    { cwd: rootDir, stdio: 'inherit', shell: true }
523→  );
524→
525→  if (!existsSync(sessionOut)) {
526→    throw new Error(`Session MCP server output not found at ${sessionOut}`);
527→  }
528→
529→  // Pi agent server uses --target=bun --format=esm because its Pi SDK deps are ESM-only.
530→  // --target=node --format=cjs leaves ESM deps as external require() calls that fail at runtime.
531→  // koffi is marked external because it's a native N-API module — bun can't inline .node binaries
532→  // and inlining its JS breaks the native binary resolution paths.
533→  // Optional: skip if package directory is missing (e.g., not synced to OSS).
534→  if (existsSync(join(piDir, 'src'))) {
535→    mkdirSync(join(piDir, 'dist'), { recursive: true });
536→    execSync(
537→      `bun build ${join(piDir, 'src', 'index.ts')} --outdir ${join(piDir, 'dist')} --target bun --format esm --external koffi`,
538→      { cwd: rootDir, stdio: 'inherit', shell: true }
539→    );
540→    if (!existsSync(piOut)) {
541→      throw new Error(`Pi agent server output not found at ${piOut}`);
542→    }
543→  } else {
544→    console.warn('Warning: Pi agent server package not found. Pi SDK sessions will not work.');
545→  }
546→}
