625→/**
626→ * Load environment variables from .env file
627→ */
628→export async function loadEnvFile(config: BuildConfig): Promise<void> {
629→  const envPath = join(config.rootDir, '.env');
630→
631→  if (existsSync(envPath)) {
632→    const content = await Bun.file(envPath).text();
633→    for (const line of content.split('\n')) {
634→      const trimmed = line.trim();
635→      if (trimmed && !trimmed.startsWith('#')) {
636→        const [key, ...valueParts] = trimmed.split('=');
637→        if (key && valueParts.length > 0) {
638→          const value = valueParts.join('=').replace(/^["']|["']$/g, '');
639→          process.env[key] = value;
640→        }
641→      }
642→    }
643→  }
644→}
