 34→function firstExistingPath(candidates: string[]): string | undefined {
 35→  for (const candidate of candidates) {
 36→    if (existsSync(candidate)) return candidate;
 37→  }
 38→  return undefined;
 39→}
 40→
 41→/**
 42→ * Walk up from `base` checking `join(ancestor, relativePath)` at each level.
 43→ * Stops after `maxLevels` ancestors or when hitting the filesystem root.
 44→ */
 45→function resolveUpwards(base: string, relativePath: string, maxLevels = 4): string | undefined {
 46→  let dir = resolve(base);
 47→  for (let i = 0; i <= maxLevels; i++) {
 48→    const candidate = join(dir, relativePath);
 49→    if (existsSync(candidate)) return candidate;
 50→    const parent = dirname(dir);
 51→    if (parent === dir) break; // filesystem root
 52→    dir = parent;
 53→  }
 54→  return undefined;
 55→}
