 57→function resolveBundledRuntimePath(hostRuntime: BackendHostRuntimeContext): string | undefined {
 58→  const bunBinary = process.platform === 'win32' ? 'bun.exe' : 'bun';
 59→  const bunBasePath = process.platform === 'win32'
 60→    ? (hostRuntime.resourcesPath || hostRuntime.appRootPath)
 61→    : hostRuntime.appRootPath;
 62→  const bunPath = join(bunBasePath, 'vendor', 'bun', bunBinary);
 63→  if (existsSync(bunPath)) return bunPath;
 64→
 65→  // Non-packaged (headless server, dev mode): fall back to system bun via PATH.
 66→  // Packaged apps must ship their own bundled bun — never resolve from PATH
 67→  // to avoid picking up an incompatible system install.
 68→  if (!hostRuntime.isPackaged) {
 69→    try {
 70→      const whichCmd = process.platform === 'win32' ? 'where' : 'which';
 71→      const systemBun = execFileSync(whichCmd, ['bun'], { encoding: 'utf-8' }).trim();
 72→      if (systemBun && existsSync(systemBun)) return systemBun;
 73→    } catch { /* system bun not found */ }
 74→  }
 75→  return undefined;
 76→}
