 78→function resolveClaudeCliPath(hostRuntime: BackendHostRuntimeContext): string | undefined {
 79→  const sdkRelative = join('node_modules', '@anthropic-ai', 'claude-agent-sdk', 'cli.js');
 80→  const result = firstExistingPath([
 81→    join(hostRuntime.appRootPath, sdkRelative),
 82→    join(hostRuntime.appRootPath, '..', '..', sdkRelative),
 83→  ]);
 84→  if (result) return result;
 85→
 86→  // Dev runtime: walk further up from .app bundle to reach monorepo root
 87→  if (IS_DEV_RUNTIME) {
 88→    return resolveUpwards(hostRuntime.appRootPath, sdkRelative, 10);
