117→function resolveCopilotCliPath(hostRuntime: BackendHostRuntimeContext): string | undefined {
118→  const platform = process.platform === 'win32'
119→    ? 'win32'
120→    : process.platform === 'linux'
121→      ? 'linux'
122→      : 'darwin';
123→  const arch = process.arch === 'arm64' ? 'arm64' : 'x64';
124→  const binaryName = platform === 'win32' ? 'copilot.exe' : 'copilot';
125→
126→  if (hostRuntime.isPackaged) {
127→    const packaged = join(hostRuntime.appRootPath, 'vendor', 'copilot', `${platform}-${arch}`, binaryName);
128→    return existsSync(packaged) ? packaged : undefined;
129→  }
130→
131→  return resolveUpwards(
132→    hostRuntime.appRootPath,
133→    join('node_modules', '@github', `copilot-${platform}-${arch}`, binaryName),
134→  );
135→}
