141→      join(hostRuntime.appRootPath, 'dist', 'resources', serverName, 'index.js'),
142→    ]);
143→  }
144→  return resolveUpwards(
145→    hostRuntime.appRootPath,
146→    join('packages', serverName, 'dist', 'index.js'),
147→  );
