316→export function copySDK(config: BuildConfig): void {
317→  const { rootDir, electronDir } = config;
318→
319→  const sdkSource = join(rootDir, 'node_modules', '@anthropic-ai', 'claude-agent-sdk');
320→  const sdkDest = join(electronDir, 'node_modules', '@anthropic-ai', 'claude-agent-sdk');
321→
322→  if (!existsSync(sdkSource)) {
323→    throw new Error(`SDK not found at ${sdkSource}. Run 'bun install' first.`);
324→  }
325→
326→  console.log('Copying SDK...');
327→  mkdirSync(dirname(sdkDest), { recursive: true });
328→  // Remove existing symlink/directory if present (bun uses symlinks)
329→  if (existsSync(sdkDest)) {
330→    rmSync(sdkDest, { recursive: true, force: true });
331→  }
332→  // Use dereference to follow symlinks and copy actual files (bun uses symlinked node_modules)
333→  cpSync(sdkSource, sdkDest, { recursive: true, dereference: true });
