339→export function verifySDKCopy(config: BuildConfig): void {
340→  const { electronDir } = config;
341→  const cliPath = join(electronDir, 'node_modules', '@anthropic-ai', 'claude-agent-sdk', 'cli.js');
342→
343→  if (!existsSync(cliPath)) {
344→    throw new Error(`SDK verification failed: cli.js not found at ${cliPath}`);
345→  }
346→
347→  const stats = lstatSync(cliPath);
348→  if (stats.isSymbolicLink()) {
349→    throw new Error('SDK verification failed: cli.js is a symlink (should be real file)');
350→  }
351→
352→  const size = stats.size;
353→  if (size < 1_000_000) {
354→    // cli.js should be ~11MB
355→    throw new Error(`SDK verification failed: cli.js too small (${size} bytes, expected ~11MB)`);
356→  }
357→
358→  console.log(`  SDK copy verified: cli.js is ${(size / 1024 / 1024).toFixed(1)} MB`);
359→}
